create table if not exists public.library_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null,title text not null,file_name text,mime_type text,size_bytes bigint,storage_path text,note_text text,favorite boolean not null default false,created_at timestamptz not null default now());alter table public.library_items enable row level security;create policy "library_own" on public.library_items for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);insert into storage.buckets(id,name,public,file_size_limit) values('kean-library','kean-library',false,52428800) on conflict(id) do nothing;
